const ENCODING = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
const ENCODING_LEN = 32;
const TIME_LEN = 10;
const RANDOM_LEN = 16;
const TIME_MAX = 281474976710655;

function encodeTime(now, len) {
  if (now > TIME_MAX) {
    throw new Error('cannot encode time: too large');
  }
  let mod;
  let str = '';
  for (let i = len; i > 0; i--) {
    mod = now % ENCODING_LEN;
    str = ENCODING.charAt(mod) + str;
    now = (now - mod) / ENCODING_LEN;
  }
  return str;
}

function encodeRandom(len) {
  let str = '';
  for (let i = 0; i < len; i++) {
    str += ENCODING.charAt(Math.floor(Math.random() * ENCODING_LEN));
  }
  return str;
}

function ulid() {
  return encodeTime(Date.now(), TIME_LEN) + encodeRandom(RANDOM_LEN);
}

const runId = ulid();
const startedAt = new Date().toISOString();

return [
  {
    json: {
      runId,
      startedAt,
      agentName: 'trend_analyst',
      workflowVersion: 'v1',
    },
  },
];

// Build OpenAI Responses API request body.
//
// Execution mode: Run Once for All Items (this node runs once with all
// upstream items; we expect exactly 1 item from `Insert run_logs started`).
//
// System prompt is base64-encoded to avoid escaping issues with unicode
// characters, emojis, and backticks (the prompt contains few-shot example
// JSON blocks with triple-backtick fences that would break a JS template
// literal).

const runMetadata = $('Generate runId').first().json;
const runId = runMetadata.runId;
const startedAt = runMetadata.startedAt;

const SYSTEM_PROMPT_B64 = '';

const SYSTEM_PROMPT = Buffer.from(SYSTEM_PROMPT_B64, 'base64').toString('utf8');

const RESPONSE_FORMAT = {
  "name": "trend_analyst_output",
  "strict": true,
  "schema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "properties": {
      "signals": {
        "maxItems": 30,
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "brand": {
              "type": "string",
              "minLength": 1,
              "maxLength": 80,
              "description": "Perfume house / brand name (e.g. \"Maison Francis Kurkdjian\"). No abbreviations."
            },
            "brand_line": {
              "anyOf": [
                {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 80
                },
                {
                  "type": "null"
                }
              ],
              "description": "Specific premium line within the brand when applicable (e.g. \"Les Exclusifs\" for Chanel, \"La Collection Privée\" for Dior, \"Private Blend\" for Tom Ford, \"Hermessence\" for Hermès, \"Le Vestiaire des Parfums\" for YSL). Use null when the brand has no internal line distinction OR when the fragrance is from the mainline. Examples: Chanel Bleu de Chanel → null; Chanel N°1957 → \"Les Exclusifs\". Dior Sauvage → null; Dior Gris Dior → \"La Collection Privée\". Be explicit: an omitted key is a validation error — emit null deliberately when there is no line."
            },
            "fragrance_name": {
              "type": "string",
              "minLength": 1,
              "maxLength": 120,
              "description": "Commercial fragrance name as listed by the house (e.g. \"Baccarat Rouge 540 Extrait\"). Include concentration / flanker suffix when applicable."
            },
            "demand_score": {
              "type": "integer",
              "minimum": 0,
              "maximum": 100,
              "description": "Integer 0-100 estimating relative demand among Mexican high-net-worth fragrance buyers. 0 = ignored, 100 = unmissable cultural moment."
            },
            "velocity_7d": {
              "type": "number",
              "minimum": -100,
              "maximum": 100,
              "description": "Percentage change in interest over the last 7 days. Negative values indicate decline — emit them when the trend is fading."
            },
            "sentiment": {
              "type": "string",
              "enum": [
                "positive",
                "mixed",
                "hype_only"
              ],
              "description": "Aggregate community sentiment. \"positive\" = genuinely loved, \"mixed\" = divisive but discussed, \"hype_only\" = trending without substance."
            },
            "sources": {
              "minItems": 1,
              "maxItems": 10,
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 200
              },
              "description": "Free-text identifiers of the sources consulted (e.g. \"Reddit r/fragrance\", \"Google Trends MX\", \"Fragrantica reviews\"). Not URLs."
            },
            "evidence_quotes": {
              "minItems": 1,
              "maxItems": 10,
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 500
              },
              "description": "Short verbatim quotes or paraphrases that justify the demand_score. Each item is one quote — do not concatenate."
            },
            "reasoning_summary": {
              "type": "string",
              "minLength": 50,
              "maxLength": 400,
              "description": "One- to two-sentence analytical synthesis of why this signal matters right now. Distinct from evidence_quotes (which are verbatim citations from sources): this is your takeaway interpreting those quotes against current 2026 market trends. Example: \"Sustained TikTok pickup in Mexico CDMX paired with the 2026 oud revival; Khamrah is the gateway SKU pulling first-time buyers into Arab perfumery.\" Avoid generic phrases like \"trending\" or \"popular\" — name the mechanism."
            },
            "confidence": {
              "type": "number",
              "minimum": 0,
              "maximum": 1,
              "description": "Model self-reported confidence in this signal, in [0, 1]. Anything below 0.7 will be dropped downstream — be honest."
            }
          },
          "required": [
            "brand",
            "brand_line",
            "fragrance_name",
            "demand_score",
            "velocity_7d",
            "sentiment",
            "sources",
            "evidence_quotes",
            "reasoning_summary",
            "confidence"
          ],
          "additionalProperties": false
        },
        "description": "Up to 30 trend signals discovered during this run. May be empty."
      }
    },
    "required": [
      "signals"
    ],
    "additionalProperties": false
  }
};

const userMessage =
  `Run the Trend Analyst now. Run ID: ${runId}. ` +
  `Timestamp: ${startedAt}. ` +
  `Analyze the Mexican HNW fragrance market for the last 7 days. ` +
  `Surface 10-20 high-quality signals following the rules in your instructions.`;

const requestBody = {
  model: 'gpt-5.4',
  instructions: SYSTEM_PROMPT,
  input: [
    {
      role: 'user',
      content: userMessage,
    },
  ],
  tools: [
    { type: 'web_search' },
  ],
  text: {
    format: {
      type: 'json_schema',
      ...RESPONSE_FORMAT,
    },
  },
  reasoning: {
    effort: 'low',
  },
  store: false,
};

return [
  {
    json: requestBody,
  },
];

const DEMAND_SCORE_THRESHOLD = 60;
const CONFIDENCE_THRESHOLD = 0.7;

const TAXONOMY = {
  'Maison Francis Kurkdjian': { mainline: 'A' },
  'Le Labo': { mainline: 'A' },
  'Byredo': { mainline: 'A' },
  'Chanel': { mainline: 'D', lines: { 'Les Exclusifs': 'A' } },
  'Hermès': { lines: { 'Hermessence': 'A' } },
  'Frédéric Malle': { mainline: 'A', lines: { 'Editions de Parfums': 'A' } },
  'Matière Première': { mainline: 'A' },
  'Diptyque': { mainline: 'A' },
  'Xinú': { mainline: 'A' },
  'Maison Margiela': { lines: { 'Replica': 'A' } },
  'Creed': { mainline: 'B' },
  'Parfums de Marly': { mainline: 'B' },
  'Initio Parfums Privés': { mainline: 'B' },
