  'Stéphane Humbert Lucas': { mainline: 'C' },
  'Paco Rabanne': { mainline: 'D' },
  'Carolina Herrera': { mainline: 'D' },
  'Versace': { mainline: 'D' },
  'Lattafa': { mainline: 'D', lines: { 'Pride': 'E', 'Niche Emarati': 'E' } },
