  'Alexandria Fragrances': { mainline: 'F' },
  'Calvin Klein': { mainline: 'F' },
  'Hugo Boss': { mainline: 'F' },
  'Dolce & Gabbana': { mainline: 'F' },
  'Burberry': { mainline: 'F' },
  'Montblanc': { mainline: 'F' },
};

function normalizeBrandString(s) {
  return s.trim().normalize('NFC');
}

function resolveBucket(brand, brand_line) {
  const normalized = normalizeBrandString(brand);
  const entry = TAXONOMY[normalized];
  if (!entry) return null;
  if (brand_line === null) {
    return entry.mainline ?? null;
  }
  const lineKey = brand_line.trim();
  return entry.lines?.[lineKey] ?? null;
}

function isKnownBrand(brand) {
  return TAXONOMY[normalizeBrandString(brand)] !== undefined;
}

const runId = $('Generate runId').first().json.runId;
const openaiResponse = $('OpenAI Responses').first().json.body;

let rawJsonString = null;
if (openaiResponse?.output && Array.isArray(openaiResponse.output)) {
  for (const outputItem of openaiResponse.output) {
    if (outputItem.type === 'message' && Array.isArray(outputItem.content)) {
      for (const contentItem of outputItem.content) {
        if (contentItem.type === 'output_text' && typeof contentItem.text === 'string') {
          rawJsonString = contentItem.text;
          break;
        }
      }
    }
    if (rawJsonString) break;
  }
}

if (!rawJsonString) {
  return [
    {
      json: {
        status: 'parse_failed',
        runId,
        error: 'Could not locate output_text in OpenAI response.',
        rawResponse: openaiResponse,
      },
    },
  ];
}

let parsed;
try {
  parsed = JSON.parse(rawJsonString);
} catch (err) {
  return [
    {
      json: {
        status: 'parse_failed',
        runId,
        error: `JSON.parse failed: ${err.message}`,
        rawJsonString: rawJsonString.slice(0, 500),
      },
    },
  ];
}

if (!parsed || !Array.isArray(parsed.signals)) {
  return [
    {
      json: {
        status: 'parse_failed',
        runId,
        error: 'Parsed object missing signals array.',
        parsed,
      },
    },
  ];
}

const known = [];
const unknown = [];
const excluded = [];
const filteredOut = [];

for (const signal of parsed.signals) {
  const bucket = resolveBucket(signal.brand, signal.brand_line);

  if (bucket === null) {
    unknown.push({
      signal,
      knownBrand: isKnownBrand(signal.brand),
    });
    continue;
  }

  if (bucket === 'F') {
    excluded.push({ signal, bucket: 'F' });
    continue;
  }

  const demandFails = signal.demand_score < DEMAND_SCORE_THRESHOLD;
  const confidenceFails = signal.confidence < CONFIDENCE_THRESHOLD;

  if (demandFails || confidenceFails) {
    let reason;
    if (demandFails && confidenceFails) reason = 'both_too_low';
    else if (demandFails) reason = 'demand_score_too_low';
    else reason = 'confidence_too_low';
    filteredOut.push({ signal, bucket, reason });
    continue;
  }

  known.push({ signal, bucket });
}

return [
  {
    json: {
      status: 'ok',
      runId,
      totalSignals: parsed.signals.length,
      known,
      unknown,
      excluded,
      filteredOut,
      counts: {
        known: known.length,
        unknown: unknown.length,
        excluded: excluded.length,
        filteredOut: filteredOut.length,
      },
    },
  },
];

