    brand: $json.signal.brand,
    brand_line: $json.signal.brand_line,
    fragrance_name: $json.signal.fragrance_name,
    demand_score: $json.signal.demand_score,
    velocity_7d: $json.signal.velocity_7d,
    sentiment: $json.signal.sentiment,
    sources: $json.signal.sources,
    evidence_quotes: $json.signal.evidence_quotes,
    reasoning_summary: $json.signal.reasoning_summary,
    confidence: $json.signal.confidence,
    bucket: $json.bucket,
    run_id: runId,
  },
